import React, { useState, useEffect } from 'react';
import { 
  Container, Row, Col, Card, Form, Button, 
  Alert, Tab, Tabs, Badge, ListGroup, 
  Modal, ProgressBar, Spinner, Toast
} from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useNotification } from '../contexts/NotificationContext';
import { useAnalytics } from '../contexts/AnalyticsContext';

const ProfilePage = () => {
  const { user, updateProfile, logout, changePassword } = useAuth();
  const { getDashboardData, getRecentSearches, clearAnalytics } = useAnalytics();
  const { addNotification } = useNotification();
  const navigate = useNavigate();
  
  const [activeTab, setActiveTab] = useState('profile');
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [dashboardData, setDashboardData] = useState(null);
  const [recentSearches, setRecentSearches] = useState([]);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [exportingData, setExportingData] = useState(false);
  const [deleteConfirmText, setDeleteConfirmText] = useState('');
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem('darkMode') === 'true';
  });

  // Initialize form with user data
  useEffect(() => {
    if (user) {
      setFormData(prev => ({
        ...prev,
        name: user.name || '',
        email: user.email || ''
      }));
      
      loadUserData();
    }
  }, [user]);

  const loadUserData = async () => {
    try {
      // Load dashboard data
      const dashboard = getDashboardData();
      setDashboardData(dashboard);
      
      // Load recent searches
      const searches = getRecentSearches();
    
     // Filter hanya untuk user yang sedang login
      const userSearches = searches.filter(search => 
      search.user_id === user.id
    );
    
      setRecentSearches(userSearches);
    } catch (error) {
      console.error('Error loading user data:', error);
    }
  };

  const validateProfileForm = () => {
    const newErrors = {};
    
    if (!formData.name.trim()) {
      newErrors.name = 'Nama diperlukan';
    } else if (formData.name.trim().length < 2) {
      newErrors.name = 'Nama minimal 2 karakter';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const validatePasswordForm = () => {
    const newErrors = {};
    
    if (!formData.currentPassword) {
      newErrors.currentPassword = 'Password saat ini diperlukan';
    } else if (formData.currentPassword.length < 6) {
      newErrors.currentPassword = 'Password minimal 6 karakter';
    }
    
    if (!formData.newPassword) {
      newErrors.newPassword = 'Password baru diperlukan';
    } else if (formData.newPassword.length < 6) {
      newErrors.newPassword = 'Password minimal 6 karakter';
    } else if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/.test(formData.newPassword)) {
      newErrors.newPassword = 'Password harus mengandung huruf besar, kecil dan angka';
    }
    
    if (!formData.confirmPassword) {
      newErrors.confirmPassword = 'Konfirmasi password diperlukan';
    } else if (formData.newPassword !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Password tidak cocok';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleUpdateProfile = async (e) => {
    e.preventDefault();
    
    if (!validateProfileForm()) return;
    
    setLoading(true);
    try {
      await updateProfile(formData.name);
      addNotification({
        type: 'success',
        message: 'Profil berhasil diperbarui'
      });
    } catch (error) {
      addNotification({
        type: 'error',
        message: 'Gagal update profil: ' + error.message
      });
    } finally {
      setLoading(false);
    }
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    
    if (!validatePasswordForm()) return;
    
    setLoading(true);
    try {
      await changePassword(
        formData.currentPassword,
        formData.newPassword
      );
      
      addNotification({
        type: 'success',
        message: 'Password berhasil diubah'
      });
      
      // Reset password fields
      setFormData(prev => ({
        ...prev,
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      }));
      
      setErrors({});
    } catch (error) {
      addNotification({
        type: 'error',
        message: 'Gagal mengubah password: ' + error.message
      });
    } finally {
      setLoading(false);
    }
  };

  const handleExportData = async () => {
    try {
      setExportingData(true);
      
      // Simulate export process
      setTimeout(() => {
        // Create CSV data
        const csvContent = [
          ['Data Type', 'Value', 'Timestamp'],
          ['User ID', user?.id, new Date().toISOString()],
          ['Email', user?.email, new Date().toISOString()],
          ['Name', user?.name, new Date().toISOString()],
          ['Account Created', user?.created_at, new Date().toISOString()],
          ['Total Searches', dashboardData?.summary?.total_searches || 0, new Date().toISOString()],
          ['Vendors Tracked', dashboardData?.summary?.vendors_tracked || 0, new Date().toISOString()],
          ['Packages Found', dashboardData?.summary?.packages_found || 0, new Date().toISOString()]
        ].map(row => row.join(',')).join('\n');
        
        // Create download
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `spse-profile-${user?.email}-${Date.now()}.csv`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
        
        addNotification({
          type: 'success',
          message: 'Data profil berhasil diexport'
        });
        setExportingData(false);
      }, 1500);
    } catch (error) {
      addNotification({
        type: 'error',
        message: 'Gagal export data: ' + error.message
      });
      setExportingData(false);
    }
  };

  const handleDeleteAccount = async () => {
    if (deleteConfirmText !== 'DELETE') {
      addNotification({
        type: 'error',
        message: 'Ketik "DELETE" untuk konfirmasi'
      });
      return;
    }
    
    try {
      setLoading(true);
      
      // Placeholder for delete account functionality
      // In production, call API to delete account
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      addNotification({
        type: 'success',
        message: 'Akun berhasil dihapus. Anda akan logout...'
      });
      
      setTimeout(() => {
        logout();
        navigate('/');
      }, 2000);
      
      setShowDeleteModal(false);
      setDeleteConfirmText('');
    } catch (error) {
      addNotification({
        type: 'error',
        message: 'Gagal menghapus akun: ' + error.message
      });
    } finally {
      setLoading(false);
    }
  };

  const handleToggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);
    localStorage.setItem('darkMode', newDarkMode.toString());
    
    // Apply dark mode class to body
    if (newDarkMode) {
      document.body.classList.add('dark-mode');
    } else {
      document.body.classList.remove('dark-mode');
    }
    
    addNotification({
      type: 'success',
      message: `Mode ${newDarkMode ? 'gelap' : 'terang'} diaktifkan`
    });
  };

  const handleToggleNotifications = () => {
    const currentSetting = localStorage.getItem('notifications') !== 'false';
    const newSetting = !currentSetting;
    localStorage.setItem('notifications', newSetting.toString());
    
    addNotification({
      type: 'success',
      message: `Notifikasi ${newSetting ? 'diaktifkan' : 'dinonaktifkan'}`
    });
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Tidak tersedia';
    return new Date(dateString).toLocaleDateString('id-ID', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const getAccountAge = () => {
    if (!user?.created_at) return '0 hari';
    const created = new Date(user.created_at);
    const now = new Date();
    const diffTime = Math.abs(now - created);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays < 30) return `${diffDays} hari`;
    if (diffDays < 365) return `${Math.floor(diffDays/30)} bulan`;
    return `${Math.floor(diffDays/365)} tahun`;
  };

  const getActivityLevel = () => {
    const totalSearches = dashboardData?.summary?.total_searches || 0;
    if (totalSearches === 0) return { label: 'Pemula', color: 'secondary' };
    if (totalSearches < 10) return { label: 'Aktif', color: 'info' };
    if (totalSearches < 50) return { label: 'Super Aktif', color: 'success' };
    return { label: 'Expert', color: 'warning' };
  };

  if (!user) {
    return (
      <Container className="py-5 text-center">
        <Alert variant="warning">
          <Alert.Heading>
            <i className="fas fa-exclamation-triangle me-2"></i>
            Akses Ditolak
          </Alert.Heading>
          <p>Anda harus login untuk mengakses halaman profil.</p>
          <Button variant="primary" onClick={() => navigate('/auth')}>
            <i className="fas fa-sign-in-alt me-2"></i>
            Login Sekarang
          </Button>
        </Alert>
      </Container>
    );
  }

  const activityLevel = getActivityLevel();

  return (
    <Container className="py-4">
      {/* Header */}
      <div className="header-gradient mb-4 p-4 rounded" style={{
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        boxShadow: '0 10px 30px rgba(0,0,0,0.15)'
      }}>
        <Row className="align-items-center">
          <Col md={8}>
            <h1 className="display-6 fw-bold text-white mb-2">
              <i className="fas fa-user-circle me-3"></i>Profil Pengguna
            </h1>
            <p className="lead mb-0 text-white opacity-90">
              Kelola akun dan data pencarian Anda
            </p>
          </Col>
          <Col md={4} className="text-md-end">
            <Badge bg="light" text="dark" className="fs-6 me-2">
              <i className="fas fa-user me-1"></i>
              {user.name}
            </Badge>
            <Badge bg={activityLevel.color} className="fs-6">
              <i className="fas fa-signal me-1"></i>
              {activityLevel.label}
            </Badge>
          </Col>
        </Row>
      </div>

      <Row>
        {/* Sidebar */}
        <Col md={4} lg={3} className="mb-4">
          <Card className="border-0 shadow-sm sticky-top" style={{ top: '90px' }}>
            <Card.Body className="text-center">
              <div className="mb-3">
                <div className="profile-avatar mx-auto mb-3">
                  <i className="fas fa-user-circle fa-4x text-primary"></i>
                </div>
                <h4 className="mb-1">{user.name}</h4>
                <p className="text-muted small mb-3">{user.email}</p>
                <Badge bg="info" className="mb-3">
                  <i className="fas fa-calendar me-1"></i>
                  Bergabung: {getAccountAge()}
                </Badge>
              </div>
              
              <ListGroup variant="flush" className="text-start">
                <ListGroup.Item 
                  action 
                  active={activeTab === 'profile'}
                  onClick={() => setActiveTab('profile')}
                  className="border-0"
                >
                  <i className="fas fa-user me-2"></i>
                  Informasi Profil
                </ListGroup.Item>
                <ListGroup.Item 
                  action 
                  active={activeTab === 'security'}
                  onClick={() => setActiveTab('security')}
                  className="border-0"
                >
                  <i className="fas fa-shield-alt me-2"></i>
                  Keamanan
                </ListGroup.Item>
                <ListGroup.Item 
                  action 
                  active={activeTab === 'activity'}
                  onClick={() => setActiveTab('activity')}
                  className="border-0"
                >
                  <i className="fas fa-chart-line me-2"></i>
                  Aktivitas
                </ListGroup.Item>
                <ListGroup.Item 
                  action 
                  active={activeTab === 'settings'}
                  onClick={() => setActiveTab('settings')}
                  className="border-0"
                >
                  <i className="fas fa-cog me-2"></i>
                  Pengaturan
                </ListGroup.Item>
              </ListGroup>
              
              <div className="mt-4 pt-3 border-top">
                <Button 
                  variant="outline-danger" 
                  size="sm" 
                  className="w-100"
                  onClick={() => logout()}
                >
                  <i className="fas fa-sign-out-alt me-2"></i>
                  Logout
                </Button>
              </div>
            </Card.Body>
          </Card>
        </Col>

        {/* Main Content */}
        <Col md={8} lg={9}>
          <Tabs
            activeKey={activeTab}
            onSelect={(k) => setActiveTab(k)}
            className="mb-4"
            fill
          >
            {/* Tab 1: Profil */}
            <Tab eventKey="profile" title="Profil">
              <Card className="border-0 shadow-sm">
                <Card.Body>
                  <Card.Title className="mb-4">
                    <i className="fas fa-user-edit me-2"></i>
                    Informasi Profil
                  </Card.Title>
                  
                  <Form onSubmit={handleUpdateProfile}>
                    <Row className="g-3">
                      <Col md={6}>
                        <Form.Group>
                          <Form.Label>Nama Lengkap</Form.Label>
                          <Form.Control
                            type="text"
                            value={formData.name}
                            onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                            isInvalid={!!errors.name}
                            placeholder="Masukkan nama lengkap"
                            disabled={loading}
                          />
                          <Form.Control.Feedback type="invalid">
                            {errors.name}
                          </Form.Control.Feedback>
                        </Form.Group>
                      </Col>
                      
                      <Col md={6}>
                        <Form.Group>
                          <Form.Label>Email</Form.Label>
                          <Form.Control
                            type="email"
                            value={formData.email}
                            disabled
                            readOnly
                            className="bg-light"
                          />
                          <Form.Text className="text-muted">
                            Email tidak dapat diubah
                          </Form.Text>
                        </Form.Group>
                      </Col>
                      
                      <Col md={6}>
                        <Form.Group>
                          <Form.Label>Tanggal Bergabung</Form.Label>
                          <Form.Control
                            type="text"
                            value={formatDate(user.created_at)}
                            disabled
                            readOnly
                            className="bg-light"
                          />
                        </Form.Group>
                      </Col>
                      
                      <Col md={6}>
                        <Form.Group>
                          <Form.Label>ID Pengguna</Form.Label>
                          <Form.Control
                            type="text"
                            value={user.id || 'N/A'}
                            disabled
                            readOnly
                            className="bg-light"
                          />
                        </Form.Group>
                      </Col>
                      
                      <Col md={12} className="mt-4">
                        <Button 
                          type="submit" 
                          variant="primary"
                          disabled={loading}
                        >
                          {loading ? (
                            <>
                              <span className="spinner-border spinner-border-sm me-2"></span>
                              Menyimpan...
                            </>
                          ) : (
                            <>
                              <i className="fas fa-save me-2"></i>
                              Simpan Perubahan
                            </>
                          )}
                        </Button>
                      </Col>
                    </Row>
                  </Form>
                </Card.Body>
              </Card>
            </Tab>

            {/* Tab 2: Keamanan */}
            <Tab eventKey="security" title="Keamanan">
              <Card className="border-0 shadow-sm">
                <Card.Body>
                  <Card.Title className="mb-4">
                    <i className="fas fa-shield-alt me-2"></i>
                    Keamanan Akun
                  </Card.Title>
                  
                  <Alert variant="info" className="mb-4">
                    <i className="fas fa-info-circle me-2"></i>
                    Untuk keamanan akun Anda, pastikan password selalu kuat dan rahasia.
                    <br />
                    <small>Password harus minimal 6 karakter dan mengandung huruf besar, kecil, dan angka.</small>
                  </Alert>
                  
                  <Form onSubmit={handleChangePassword}>
                    <Row className="g-3">
                      <Col md={12}>
                        <Form.Group>
                          <Form.Label>Password Saat Ini</Form.Label>
                          <Form.Control
                            type="password"
                            value={formData.currentPassword}
                            onChange={(e) => setFormData(prev => ({ ...prev, currentPassword: e.target.value }))}
                            isInvalid={!!errors.currentPassword}
                            placeholder="Masukkan password saat ini"
                            disabled={loading}
                          />
                          <Form.Control.Feedback type="invalid">
                            {errors.currentPassword}
                          </Form.Control.Feedback>
                        </Form.Group>
                      </Col>
                      
                      <Col md={6}>
                        <Form.Group>
                          <Form.Label>Password Baru</Form.Label>
                          <Form.Control
                            type="password"
                            value={formData.newPassword}
                            onChange={(e) => setFormData(prev => ({ ...prev, newPassword: e.target.value }))}
                            isInvalid={!!errors.newPassword}
                            placeholder="Minimal 6 karakter"
                            disabled={loading}
                          />
                          <Form.Control.Feedback type="invalid">
                            {errors.newPassword}
                          </Form.Control.Feedback>
                        </Form.Group>
                      </Col>
                      
                      <Col md={6}>
                        <Form.Group>
                          <Form.Label>Konfirmasi Password Baru</Form.Label>
                          <Form.Control
                            type="password"
                            value={formData.confirmPassword}
                            onChange={(e) => setFormData(prev => ({ ...prev, confirmPassword: e.target.value }))}
                            isInvalid={!!errors.confirmPassword}
                            placeholder="Ulangi password baru"
                            disabled={loading}
                          />
                          <Form.Control.Feedback type="invalid">
                            {errors.confirmPassword}
                          </Form.Control.Feedback>
                        </Form.Group>
                      </Col>
                      
                      <Col md={12} className="mt-4">
                        <Button 
                          type="submit" 
                          variant="warning"
                          disabled={loading}
                        >
                          {loading ? (
                            <>
                              <span className="spinner-border spinner-border-sm me-2"></span>
                              Memproses...
                            </>
                          ) : (
                            <>
                              <i className="fas fa-key me-2"></i>
                              Ubah Password
                            </>
                          )}
                        </Button>
                      </Col>
                    </Row>
                  </Form>
                  
                  <div className="mt-5 pt-4 border-top">
                    <h6 className="mb-3">
                      <i className="fas fa-trash-alt me-2 text-danger"></i>
                      Hapus Akun
                    </h6>
                    <Alert variant="danger">
                      <Alert.Heading>
                        <i className="fas fa-exclamation-triangle me-2"></i>
                        Peringatan!
                      </Alert.Heading>
                      <p>
                        Menghapus akun akan menghapus semua data pencarian, favorit, dan riwayat Anda.
                        Tindakan ini tidak dapat dibatalkan.
                      </p>
                      <Button 
                        variant="outline-danger" 
                        size="sm"
                        onClick={() => setShowDeleteModal(true)}
                      >
                        <i className="fas fa-trash me-2"></i>
                        Hapus Akun Saya
                      </Button>
                    </Alert>
                  </div>
                </Card.Body>
              </Card>
            </Tab>

            {/* Tab 3: Aktivitas */}
            <Tab eventKey="activity" title="Aktivitas">
              <Card className="border-0 shadow-sm mb-4">
                <Card.Body>
                      <Card.Title className="mb-4 d-flex justify-content-between align-items-center">
                        <span>
                          <i className="fas fa-history me-2"></i>
                          Pencarian Terakhir
                        </span>
                        {recentSearches.length > 0 && (
                          <Button 
                            variant="outline-danger" 
                            size="sm"
                            onClick={() => {
                              if (window.confirm('Hapus semua riwayat pencarian?')) {
                                clearAnalytics();
                                setRecentSearches([]);
                                loadUserData();
                                addNotification({
                                  type: 'success',
                                  message: 'Riwayat pencarian berhasil dihapus'
                                });
                              }
                            }}
                          >
                            <i className="fas fa-trash me-1"></i> Clear History
                          </Button>
                        )}
                      </Card.Title>
                  
                  {dashboardData ? (
                    <Row>
                      <Col md={3} className="mb-3">
                        <div className="text-center p-3 border rounded bg-light">
                          <div className="display-6 fw-bold text-primary">
                            {dashboardData.summary?.total_searches || 0}
                          </div>
                          <div className="small text-muted">
                            <i className="fas fa-search me-1"></i>
                            Total Pencarian
                          </div>
                        </div>
                      </Col>
                      
                      <Col md={3} className="mb-3">
                        <div className="text-center p-3 border rounded bg-light">
                          <div className="display-6 fw-bold text-success">
                            {dashboardData.summary?.vendors_tracked || 0}
                          </div>
                          <div className="small text-muted">
                            <i className="fas fa-building me-1"></i>
                            Vendor Dilacak
                          </div>
                        </div>
                      </Col>
                      
                      <Col md={3} className="mb-3">
                        <div className="text-center p-3 border rounded bg-light">
                          <div className="display-6 fw-bold text-info">
                            {dashboardData.summary?.packages_found || 0}
                          </div>
                          <div className="small text-muted">
                            <i className="fas fa-box me-1"></i>
                            Paket Ditemukan
                          </div>
                        </div>
                      </Col>
                      
                      <Col md={3} className="mb-3">
                        <div className="text-center p-3 border rounded bg-light">
                          <div className="display-6 fw-bold text-warning">
                            {dashboardData.summary?.export_count || 0}
                          </div>
                          <div className="small text-muted">
                            <i className="fas fa-download me-1"></i>
                            Data Diexport
                          </div>
                        </div>
                      </Col>
                    </Row>
                  ) : (
                    <div className="text-center py-4">
                      <Spinner animation="border" variant="primary" />
                      <p className="mt-3">Memuat statistik...</p>
                    </div>
                  )}
                </Card.Body>
              </Card>
              
              <Card className="border-0 shadow-sm">
                <Card.Body>
                  <Card.Title className="mb-4">
                    <i className="fas fa-history me-2"></i>
                    Pencarian Terakhir
                  </Card.Title>
                  
                  {recentSearches.length > 0 ? (
                    <div className="table-responsive">
                      <table className="table table-hover">
                        <thead>
                          <tr>
                            <th>Waktu</th>
                            <th>Tipe</th>
                            <th>Pencarian</th>
                            <th>Hasil</th>
                            <th>Parameter</th>
                            <th>Aksi</th>
                          </tr>
                        </thead>
                        <tbody>
                          {recentSearches.slice(0, 10).map((search, index) => (
                            <tr key={search.id || index}>
                              <td>
                                <small className="text-muted">
                                  {new Date(search.timestamp).toLocaleDateString('id-ID')}
                                  <br />
                                  {new Date(search.timestamp).toLocaleTimeString('id-ID', {
                                    hour: '2-digit',
                                    minute: '2-digit'
                                  })}
                                </small>
                              </td>
                              <td>
                                <Badge bg={search.search_type === 'vendor' ? 'primary' : 'success'}>
                                  {search.search_type === 'vendor' ? 'Vendor' : 'Paket'}
                                </Badge>
                              </td>
                              <td className="text-truncate" style={{ maxWidth: '200px' }}>
                                {search.search_query}
                              </td>
                              <td>
                                <Badge bg={search.result_count > 0 ? 'success' : 'secondary'}>
                                  {search.result_count} hasil
                                </Badge>
                              </td>
                              <td>
                                <Button 
                                  variant="outline-primary" 
                                  size="sm"
                                  onClick={() => {
                                    if (search.search_type === 'vendor') {
                                        navigate(`/vendor?vendor=${encodeURIComponent(search.search_query)}&tahun=${search.parameters?.tahun || '2026'}&mode=${search.parameters?.mode || 'pu'}`);
                                      } else {
                                        navigate(`/package?keyword=${encodeURIComponent(search.search_query)}&tahun=${search.parameters?.tahun || '2026'}`);
                                      }
                                    }}
                                    title="Ulangi pencarian ini"
                                 >
                                  <i className="fas fa-redo"></i>
                                </Button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  ) : (
                    <Alert variant="info">
                      <i className="fas fa-info-circle me-2"></i>
                      Belum ada riwayat pencarian. Mulai pencarian pertama Anda!
                    </Alert>
                  )}
                </Card.Body>
              </Card>
            </Tab>

            {/* Tab 4: Pengaturan */}
            <Tab eventKey="settings" title="Pengaturan">
              <Card className="border-0 shadow-sm">
                <Card.Body>
                  <Card.Title className="mb-4">
                    <i className="fas fa-cog me-2"></i>
                    Pengaturan Aplikasi
                  </Card.Title>
                  
                  <ListGroup variant="flush">
                    <ListGroup.Item className="d-flex justify-content-between align-items-center border-0">
                      <div>
                        <h6 className="mb-1">
                          <i className="fas fa-bell me-2 text-primary"></i>
                          Notifikasi
                        </h6>
                        <p className="mb-0 small text-muted">
                          Terima notifikasi untuk pencarian baru
                        </p>
                      </div>
                      <Form.Check 
                        type="switch" 
                        defaultChecked={localStorage.getItem('notifications') !== 'false'}
                        onChange={handleToggleNotifications}
                      />
                    </ListGroup.Item>
                    
                    <ListGroup.Item className="d-flex justify-content-between align-items-center border-0">
                      <div>
                        <h6 className="mb-1">
                          <i className="fas fa-moon me-2 text-primary"></i>
                          Mode Gelap
                        </h6>
                        <p className="mb-0 small text-muted">
                          Aktifkan tampilan mode gelap
                        </p>
                      </div>
                      <Form.Check 
                        type="switch" 
                        checked={darkMode}
                        onChange={handleToggleDarkMode}
                      />
                    </ListGroup.Item>
                    
                    <ListGroup.Item className="d-flex justify-content-between align-items-center border-0">
                      <div>
                        <h6 className="mb-1">
                          <i className="fas fa-download me-2 text-primary"></i>
                          Export Data
                        </h6>
                        <p className="mb-0 small text-muted">
                          Download semua data pencarian Anda
                        </p>
                      </div>
                      <Button 
                        variant="outline-primary" 
                        size="sm"
                        onClick={handleExportData}
                        disabled={exportingData}
                      >
                        {exportingData ? (
                          <>
                            <span className="spinner-border spinner-border-sm me-2"></span>
                            Export...
                          </>
                        ) : (
                          <>
                            <i className="fas fa-download me-2"></i>
                            Export
                          </>
                        )}
                      </Button>
                    </ListGroup.Item>
                    
                    <ListGroup.Item className="border-0">
                      <h6 className="mb-3">
                        <i className="fas fa-language me-2 text-primary"></i>
                        Bahasa
                      </h6>
                      <Form.Select defaultValue="id">
                        <option value="id">Bahasa Indonesia</option>
                        <option value="en">English</option>
                      </Form.Select>
                    </ListGroup.Item>
                    
                    <ListGroup.Item className="border-0">
                      <h6 className="mb-3">
                        <i className="fas fa-chart-bar me-2 text-primary"></i>
                        Analytics
                      </h6>
                      <Form.Check 
                        type="switch" 
                        label="Kirim data analitik anonim"
                        defaultChecked
                      />
                      <Form.Text className="text-muted">
                        Membantu kami meningkatkan aplikasi
                      </Form.Text>
                    </ListGroup.Item>
                  </ListGroup>
                  
                  <div className="mt-5 pt-4 border-top">
                    <h6 className="mb-3">
                      <i className="fas fa-info-circle me-2 text-primary"></i>
                      Informasi Aplikasi
                    </h6>
                    <div className="row">
                      <div className="col-md-6">
                        <div className="mb-3">
                          <strong>Versi Aplikasi:</strong>
                          <div className="text-muted">9.0 (2026 Support)</div>
                        </div>
                        <div className="mb-3">
                          <strong>Lisensi:</strong>
                          <div className="text-muted">Open Source</div>
                        </div>
                        <div className="mb-3">
                          <strong>User ID:</strong>
                          <div className="text-muted">{user.id}</div>
                        </div>
                      </div>
                      <div className="col-md-6">
                        <div className="mb-3">
                          <strong>Dibangun dengan:</strong>
                          <div className="text-muted">React + Python Flask</div>
                        </div>
                        <div className="mb-3">
                          <strong>Support Tahun:</strong>
                          <div className="text-muted">2023 - 2026</div>
                        </div>
                        <div className="mb-3">
                          <strong>Mode Gelap:</strong>
                          <div className="text-muted">{darkMode ? 'Aktif' : 'Nonaktif'}</div>
                        </div>
                      </div>
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </Tab>
          </Tabs>
        </Col>
      </Row>

      {/* Delete Account Modal */}
      <Modal show={showDeleteModal} onHide={() => setShowDeleteModal(false)}>
        <Modal.Header closeButton className="bg-danger text-white">
          <Modal.Title>
            <i className="fas fa-exclamation-triangle me-2"></i>
            Konfirmasi Hapus Akun
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Alert variant="danger">
            <Alert.Heading>PERINGATAN!</Alert.Heading>
            <p>Anda akan menghapus akun dan semua data terkait:</p>
            <ul>
              <li>Semua riwayat pencarian</li>
              <li>Data favorit dan saved searches</li>
              <li>Statistik dan analytics</li>
              <li>Informasi profil</li>
            </ul>
            <p className="mb-0 fw-bold">Tindakan ini tidak dapat dibatalkan!</p>
          </Alert>
          
          <Form.Group className="mb-3">
            <Form.Label>
              Ketik <code className="text-danger">DELETE</code> untuk konfirmasi:
            </Form.Label>
            <Form.Control 
              type="text" 
              placeholder="Ketik DELETE"
              value={deleteConfirmText}
              onChange={(e) => setDeleteConfirmText(e.target.value)}
              className={deleteConfirmText === 'DELETE' ? 'border-success' : ''}
            />
            <Form.Text className="text-muted">
              Pastikan Anda telah mendownload semua data penting sebelum menghapus akun.
            </Form.Text>
          </Form.Group>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => {
            setShowDeleteModal(false);
            setDeleteConfirmText('');
          }}>
            <i className="fas fa-times me-1"></i>
            Batal
          </Button>
          <Button 
            variant="danger" 
            onClick={handleDeleteAccount}
            disabled={loading || deleteConfirmText !== 'DELETE'}
          >
            {loading ? (
              <>
                <span className="spinner-border spinner-border-sm me-2"></span>
                Menghapus...
              </>
            ) : (
              <>
                <i className="fas fa-trash me-2"></i>
                Hapus Akun Permanen
              </>
            )}
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default ProfilePage;